import * as THREE from '../vendor/three.module.js';

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

export function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export function hashStr(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

export function canvasTexture(w, h, draw, opts = {}) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  draw(ctx, w, h);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = opts.aniso || 8;
  if (opts.repeat) t.repeat.set(opts.repeat[0], opts.repeat[1]);
  return t;
}

/* ------------------------------ textures ----------------------------- */

export function texAsphalt() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    const img = ctx.createImageData(w, h);
    const d = img.data;
    const rnd = mulberry32(11);
    for (let i = 0; i < w * h; i++) {
      const n = rnd();
      const g = 43 + n * 32 + (rnd() > .975 ? 30 : 0);
      d[i * 4] = g; d[i * 4 + 1] = g + 1; d[i * 4 + 2] = g + 3; d[i * 4 + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
    for (let i = 0; i < 4200; i++) {
      const x = rnd() * w, y = rnd() * h, s = rnd() * 1.7 + .4;
      ctx.fillStyle = rnd() > .5 ? 'rgba(150,152,155,.18)' : 'rgba(20,21,23,.25)';
      ctx.fillRect(x, y, s, s);
    }
    ctx.globalAlpha = .1;
    for (let i = 0; i < 26; i++) {
      ctx.strokeStyle = '#202224';
      ctx.lineWidth = rnd() * 1.4 + .4;
      ctx.beginPath();
      let x = rnd() * w, y = rnd() * h;
      ctx.moveTo(x, y);
      for (let k = 0; k < 4; k++) { x += (rnd() - .5) * 60; y += (rnd() - .5) * 60; ctx.lineTo(x, y); }
      ctx.stroke();
    }
    ctx.globalAlpha = .055;
    ctx.fillStyle = '#9fa3a6';
    for (let i = 0; i < 9; i++) ctx.fillRect(rnd() * w, rnd() * h, 60 + rnd() * 180, 18 + rnd() * 60);
    ctx.globalAlpha = 1;
  });
}

export function texGrass() {
  return canvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#3c5730'; ctx.fillRect(0, 0, w, h);
    const rnd = mulberry32(23);
    for (let i = 0; i < 24000; i++) {
      const x = rnd() * w, y = rnd() * h;
      const g = 52 + rnd() * 62;
      ctx.strokeStyle = `rgba(${Math.round(g * .62)},${Math.round(g)},${Math.round(g * .42)},.5)`;
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + (rnd() - .5) * 4, y - 2 - rnd() * 5); ctx.stroke();
    }
    ctx.globalAlpha = .12;
    for (let i = 0; i < 32; i++) {
      ctx.fillStyle = i % 2 ? '#7d8a52' : '#2d4325';
      ctx.beginPath(); ctx.ellipse(rnd() * w, rnd() * h, 20 + rnd() * 60, 12 + rnd() * 30, rnd() * 3, 0, 7); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }, { aniso: 4 });
}

export function texKerb() {
  return canvasTexture(64, 64, (ctx, w, h) => {
    ctx.fillStyle = '#d8dbd2'; ctx.fillRect(0, 0, w, h / 2);
    ctx.fillStyle = '#c8342a'; ctx.fillRect(0, h / 2, w, h / 2);
    ctx.globalAlpha = .16;
    const rnd = mulberry32(4);
    for (let i = 0; i < 600; i++) {
      ctx.fillStyle = rnd() > .5 ? '#000' : '#fff';
      ctx.fillRect(rnd() * w, rnd() * h, 1.6, 1.6);
    }
  });
}

export function texCrowd() {
  return canvasTexture(256, 128, (ctx, w, h) => {
    ctx.fillStyle = '#20241f'; ctx.fillRect(0, 0, w, h);
    const rnd = mulberry32(91);
    const palette = ['#d9d6c8', '#bc3b2d', '#e0b23c', '#3f6b9c', '#e4e2d4', '#5c7a4f', '#2c3230', '#c96a3c', '#8e8f96'];
    for (let i = 0; i < 1500; i++) {
      const x = rnd() * w, y = rnd() * h;
      ctx.fillStyle = palette[(rnd() * palette.length) | 0];
      ctx.fillRect(x, y, 2.4 + rnd() * 1.6, 2.4 + rnd() * 2);
    }
    ctx.globalAlpha = .35; ctx.fillStyle = '#0a0c09';
    for (let y = 0; y < h; y += 12) ctx.fillRect(0, y, w, 1.4);
    ctx.globalAlpha = 1;
  });
}

export function texBarrier() {
  return canvasTexture(128, 64, (ctx, w, h) => {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#d6d8d2'); g.addColorStop(.45, '#9ea2a0'); g.addColorStop(.55, '#7c8180'); g.addColorStop(1, '#b8bcb8');
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(40,44,44,.5)'; ctx.lineWidth = 2;
    for (let y = 6; y < h; y += 14) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }
  });
}

export function texCarbon() {
  return canvasTexture(128, 128, (ctx, w, h) => {
    ctx.fillStyle = '#191b1e'; ctx.fillRect(0, 0, w, h);
    const cell = 8;
    for (let y = 0; y < h; y += cell) {
      for (let x = 0; x < w; x += cell) {
        const alt = ((x / cell + y / cell) | 0) % 2 === 0;
        ctx.fillStyle = alt ? '#23262a' : '#15171a';
        ctx.fillRect(x, y, cell - 1, cell - 1);
        ctx.fillStyle = 'rgba(160,168,175,.05)';
        ctx.fillRect(x + 1, y + 1, cell / 2, 1);
      }
    }
  }, { repeat: [2, 2] });
}

export function texSponsor(name, bg, fg) {
  return canvasTexture(512, 128, (ctx, w, h) => {
    ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = fg;
    ctx.font = '900 74px Arial, Helvetica, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(name, w / 2, h / 2 + 4);
    ctx.globalAlpha = .18; ctx.fillStyle = '#000';
    for (let i = 0; i < 40; i++) ctx.fillRect(Math.random() * w, Math.random() * h, 40, 3);
    ctx.globalAlpha = 1;
  });
}

export function texWindows() {
  return canvasTexture(256, 256, (ctx, w, h) => {
    ctx.fillStyle = '#8d8e86'; ctx.fillRect(0, 0, w, h);
    const rnd = mulberry32(17);
    for (let y = 8; y < h - 8; y += 18) {
      for (let x = 8; x < w - 8; x += 16) {
        ctx.fillStyle = rnd() > .82 ? '#f0e2ae' : '#3d464c';
        ctx.fillRect(x, y, 10, 10);
      }
    }
    ctx.fillStyle = 'rgba(0,0,0,.15)';
    for (let y = 0; y < h; y += 54) ctx.fillRect(0, y, w, 3);
  });
}

export function texChecker() {
  return canvasTexture(256, 64, (ctx, w, h) => {
    const n = 16, m = 4, cw = w / n, ch = h / m;
    for (let y = 0; y < m; y++) for (let x = 0; x < n; x++) {
      ctx.fillStyle = (x + y) % 2 ? '#16181a' : '#f0f0ea';
      ctx.fillRect(x * cw, y * ch, cw, ch);
    }
  });
}

export function texNumber(n, color = '#f2f2ea') {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 128, 128);
  ctx.fillStyle = color;
  ctx.font = 'italic 900 104px Arial, Helvetica, sans-serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText(String(n), 64, 70);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

export function texWheelFace(vintage) {
  return canvasTexture(256, 256, (ctx, w, h) => {
    const cx = w / 2, cy = h / 2;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#141414';
    ctx.beginPath(); ctx.arc(cx, cy, 122, 0, 7); ctx.fill();
    ctx.fillStyle = '#0c0c0c';
    ctx.beginPath(); ctx.arc(cx, cy, 116, 0, 7); ctx.fill();
    // sidewall sheen
    const sg = ctx.createRadialGradient(cx - 30, cy - 30, 20, cx, cy, 120);
    sg.addColorStop(0, 'rgba(90,90,92,.20)'); sg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = sg; ctx.beginPath(); ctx.arc(cx, cy, 118, 0, 7); ctx.fill();
    if (vintage) {
      ctx.strokeStyle = '#c9b47c'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(cx, cy, 92, 0, 7); ctx.stroke();
      ctx.fillStyle = '#b9bcc0';
      ctx.beginPath(); ctx.arc(cx, cy, 62, 0, 7); ctx.fill();
      ctx.strokeStyle = '#8b8f93'; ctx.lineWidth = 2.2;
      for (let i = 0; i < 18; i++) {
        const a = i / 18 * Math.PI * 2;
        ctx.beginPath(); ctx.moveTo(cx + Math.cos(a) * 22, cy + Math.sin(a) * 22);
        ctx.lineTo(cx + Math.cos(a) * 60, cy + Math.sin(a) * 60); ctx.stroke();
      }
      ctx.fillStyle = '#5b5f63'; ctx.beginPath(); ctx.arc(cx, cy, 20, 0, 7); ctx.fill();
    } else {
      ctx.strokeStyle = '#2f3336'; ctx.lineWidth = 5;
      ctx.beginPath(); ctx.arc(cx, cy, 107, 0, 7); ctx.stroke();
      const rim = ctx.createRadialGradient(cx - 14, cy - 14, 8, cx, cy, 72);
      rim.addColorStop(0, '#e6e8e8'); rim.addColorStop(.5, '#a6abae'); rim.addColorStop(1, '#6e7376');
      ctx.fillStyle = rim; ctx.beginPath(); ctx.arc(cx, cy, 72, 0, 7); ctx.fill();
      ctx.fillStyle = '#23272a'; ctx.beginPath(); ctx.arc(cx, cy, 56, 0, 7); ctx.fill();
      ctx.fillStyle = '#9da3a6';
      for (let i = 0; i < 10; i++) {
        const a = i / 10 * Math.PI * 2;
        ctx.save(); ctx.translate(cx, cy); ctx.rotate(a);
        ctx.fillRect(-5, 20, 10, 34); ctx.restore();
      }
      ctx.fillStyle = '#d7dadb'; ctx.beginPath(); ctx.arc(cx, cy, 17, 0, 7); ctx.fill();
      ctx.strokeStyle = '#c7402f'; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.arc(cx, cy, 84, 0, 7); ctx.stroke();
    }
  });
}

/* ------------------------------ geometry ----------------------------- */

// Loft a set of elliptical cross-sections along +Z. Sections must be ordered
// from low z to high z. Produces a smooth, closed-end-free shell.
export function loft(sections, radial = 20) {
  const pos = [], uv = [], idx = [];
  const rows = sections.length;
  for (let i = 0; i < rows; i++) {
    const s = sections[i];
    const sx = s.x || 0, sy = s.y || 0;
    for (let j = 0; j <= radial; j++) {
      const a = j / radial * Math.PI * 2;
      pos.push(sx + Math.cos(a) * s.w, sy + Math.sin(a) * s.h, s.z);
      uv.push(j / radial, i / (rows - 1));
    }
  }
  for (let i = 0; i < rows - 1; i++) {
    for (let j = 0; j < radial; j++) {
      const a = i * (radial + 1) + j, b = a + radial + 1, c = a + 1, d = b + 1;
      idx.push(a, b, c, b, d, c);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

export function strut(parent, a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 6, 1), mat);
  mesh.position.copy(a).addScaledVector(dir, .5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  mesh.castShadow = true;
  parent.add(mesh);
  return mesh;
}

export function box(w, h, d, mat) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.castShadow = true;
  return m;
}

/* --------------------------- colour helpers -------------------------- */

export function hexLum(hex) {
  const c = new THREE.Color(hex);
  return .2126 * c.r + .7152 * c.g + .0722 * c.b;
}

export function shiftColor(hex, amt) {
  const c = new THREE.Color(hex);
  c.offsetHSL(0, 0, amt);
  return '#' + c.getHexString();
}

import * as THREE from '../vendor/three.module.js';
import { loft, strut, box, clamp, texWheelFace } from './util.js';

/* Era-specific chassis prescriptions. All numbers are metres. */
export const CAR_STYLES = [
  { vintage: true, wheelR: .40, wheelW: .19, wheelbase: 2.55, trackW: 1.24, nose: 2.72, frontWing: 0, rearWing: 0, halo: false, airbox: false, sidepods: false, openCockpit: true },
  { vintage: true, wheelR: .38, wheelW: .23, wheelbase: 2.45, trackW: 1.30, nose: 2.62, frontWing: 0, rearWing: .42, halo: false, airbox: false, sidepods: false, openCockpit: true },
  { vintage: false, wheelR: .36, wheelW: .26, wheelbase: 2.55, trackW: 1.42, nose: 2.72, frontWing: 1.15, rearWing: .82, halo: false, airbox: true, sidepods: true },
  { vintage: false, wheelR: .35, wheelW: .30, wheelbase: 2.65, trackW: 1.50, nose: 2.66, frontWing: 1.45, rearWing: .92, halo: false, airbox: true, sidepods: true },
  { vintage: false, wheelR: .34, wheelW: .31, wheelbase: 2.95, trackW: 1.56, nose: 2.78, frontWing: 1.62, rearWing: .95, halo: false, airbox: true, sidepods: true },
  { vintage: false, wheelR: .34, wheelW: .33, wheelbase: 3.06, trackW: 1.60, nose: 2.86, frontWing: 1.78, rearWing: 1.00, halo: false, airbox: true, sidepods: true },
  { vintage: false, wheelR: .35, wheelW: .35, wheelbase: 3.22, trackW: 1.62, nose: 2.94, frontWing: 1.82, rearWing: 1.00, halo: true, airbox: true, sidepods: true },
  { vintage: false, wheelR: .36, wheelW: .39, wheelbase: 3.42, trackW: 1.63, nose: 3.00, frontWing: 1.95, rearWing: 1.05, halo: true, airbox: true, sidepods: true },
  { vintage: false, wheelR: .36, wheelW: .39, wheelbase: 3.58, trackW: 1.62, nose: 3.04, frontWing: 2.00, rearWing: 1.05, halo: true, airbox: true, sidepods: true }
];

export function createCarTextures() {
  return {
    carbon: null, // filled by caller
    wheelFaceVintage: texWheelFace(true),
    wheelFaceModern: texWheelFace(false)
  };
}

export function buildCar(style, opts, shared) {
  const low = !!opts.low;
  const primary = opts.primary || '#d8d9cf';
  const accent = opts.accent || '#1a1c1e';

  const paint = new THREE.MeshPhysicalMaterial({
    color: primary, metalness: .45, roughness: .26, clearcoat: 1,
    clearcoatRoughness: .09, envMapIntensity: 1.15
  });
  const accentMat = new THREE.MeshPhysicalMaterial({
    color: accent, metalness: .28, roughness: .34, clearcoat: .8,
    clearcoatRoughness: .16, envMapIntensity: 1.0
  });
  const carbon = new THREE.MeshStandardMaterial({ map: shared.carbon, color: 0xffffff, metalness: .45, roughness: .5 });
  const dark = new THREE.MeshStandardMaterial({ color: 0x0b0d0f, metalness: .45, roughness: .5 });
  const chrome = new THREE.MeshStandardMaterial({ color: 0xd8dde1, metalness: 1, roughness: .15 });
  const rubber = new THREE.MeshStandardMaterial({ color: 0x151516, metalness: .01, roughness: .94 });
  const faceMat = new THREE.MeshStandardMaterial({
    map: style.vintage ? shared.wheelFaceVintage : shared.wheelFaceModern,
    metalness: .25, roughness: .6
  });
  const glass = new THREE.MeshPhysicalMaterial({ color: 0x0a0f13, metalness: .8, roughness: .05, envMapIntensity: 1.9 });
  const brake = new THREE.MeshStandardMaterial({ color: 0x220502, emissive: 0xff1a08, emissiveIntensity: 2.6, roughness: .4 });
  const headMat = new THREE.MeshPhysicalMaterial({ color: opts.helmet || '#e9e9df', metalness: .2, roughness: .22, clearcoat: 1, clearcoatRoughness: .08, envMapIntensity: 1.2 });

  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const add = (m, parent = body) => {
    m.castShadow = true; m.receiveShadow = true; parent.add(m); return m;
  };

  const radial = low ? 12 : 22;
  const zAt = (t) => -1.95 + t * (style.nose + 1.95);

  /* ---- survival cell / bodywork ---- */
  let profile;
  if (style.vintage) {
    profile = [
      [0, .030, .045, .60], [.07, .100, .130, .60], [.18, .160, .185, .585],
      [.32, .215, .215, .565], [.46, .235, .225, .55], [.60, .225, .22, .54],
      [.72, .185, .20, .525], [.84, .130, .155, .51], [.94, .070, .09, .50],
      [1, .022, .030, .49]
    ];
  } else {
    profile = [
      [0, .045, .065, .40], [.08, .120, .145, .42], [.18, .200, .220, .45],
      [.30, .285, .250, .48], [.42, .325, .265, .50], [.52, .335, .275, .51],
      [.62, .305, .250, .49], [.72, .230, .185, .42], [.82, .150, .120, .33],
      [.92, .080, .070, .25], [1, .018, .024, .21]
    ];
  }
  const sections = profile.map(([t, w, h, y]) => ({ z: zAt(t), w, h, y }));
  add(new THREE.Mesh(loft(sections, radial), paint));

  const cockpitZ = zAt(style.vintage ? .60 : .52);
  const topY = style.vintage ? .775 : .785;

  /* ---- floor / plank ---- */
  if (!low) {
    const floor = box(style.vintage ? .72 : 1.02, .055, style.vintage ? 3.1 : 4.3, carbon);
    floor.position.set(0, .125, style.vintage ? -.1 : .25);
    add(floor);
  }

  /* ---- sidepods ---- */
  if (style.sidepods) {
    for (const s of [-1, 1]) {
      const pod = [
        { z: zAt(.12), x: s * .27, w: .035, h: .06, y: .42 },
        { z: zAt(.20), x: s * .41, w: .10, h: .14, y: .405 },
        { z: zAt(.32), x: s * .46, w: .17, h: .19, y: .395 },
        { z: zAt(.45), x: s * .47, w: .19, h: .20, y: .385 },
        { z: zAt(.57), x: s * .44, w: .17, h: .19, y: .395 },
        { z: zAt(.67), x: s * .37, w: .10, h: .13, y: .42 }
      ];
      add(new THREE.Mesh(loft(pod, radial), paint));
      if (!low) {
        const inlet = new THREE.Mesh(new THREE.CircleGeometry(1, 16), dark);
        inlet.scale.set(.135, .16, 1);
        inlet.position.set(s * .41, .405, zAt(.205));
        inlet.rotation.y = s > 0 ? 0 : Math.PI;
        add(inlet);
      }
    }
  }

  /* ---- cockpit, driver, halo ---- */
  const opening = new THREE.Mesh(new THREE.CircleGeometry(1, 20), dark);
  opening.scale.set(style.vintage ? .20 : .23, style.vintage ? .34 : .40, 1);
  opening.rotation.x = -Math.PI / 2;
  opening.position.set(0, topY + .012, cockpitZ);
  add(opening);

  const helmet = new THREE.Mesh(new THREE.SphereGeometry(.125, 18, 14), headMat);
  helmet.scale.set(1, .96, 1.06);
  helmet.position.set(0, style.vintage ? .80 : .80, cockpitZ + .02);
  add(helmet);
  const visor = box(.20, .062, .05, glass);
  visor.position.set(0, helmet.position.y + .012, cockpitZ + .115);
  add(visor);

  if (!style.vintage) {
    const halo = new THREE.Mesh(new THREE.TorusGeometry(.29, .028, 7, 22, Math.PI), carbon);
    halo.rotation.x = Math.PI / 2;
    halo.rotation.z = 0;
    halo.position.set(0, .81, cockpitZ - .02);
    add(halo);
    const pillar = box(.05, .24, .05, carbon);
    pillar.position.set(0, .88, cockpitZ + .46);
    pillar.rotation.x = -.16;
    add(pillar);
    const hoop = new THREE.Mesh(new THREE.TorusGeometry(.26, .032, 7, 18, Math.PI), carbon);
    hoop.position.set(0, .84, cockpitZ - .52);
    add(hoop);
  } else {
    const screen = new THREE.Mesh(new THREE.PlaneGeometry(.46, .20), glass);
    screen.position.set(0, .90, zAt(.72));
    screen.rotation.x = -.42;
    screen.material.side = THREE.DoubleSide;
    add(screen);
    const fairing = new THREE.Mesh(new THREE.SphereGeometry(.20, 14, 10), paint);
    fairing.scale.set(.9, .8, 1.5);
    fairing.position.set(0, .80, cockpitZ - .55);
    add(fairing);
  }

  /* ---- airbox / roll hoop ---- */
  if (style.airbox) {
    const air = [
      { z: -.62, w: .06, h: .07, y: .80 }, { z: -.42, w: .15, h: .14, y: .85 },
      { z: -.18, w: .16, h: .15, y: .89 }, { z: -.02, w: .10, h: .10, y: .91 }
    ];
    add(new THREE.Mesh(loft(air, radial), paint));
  } else if (!style.halo) {
    const hoop = new THREE.Mesh(new THREE.TorusGeometry(.22, .03, 6, 16, Math.PI), carbon);
    hoop.position.set(0, .80, cockpitZ - .62);
    add(hoop);
  }

  /* ---- wings ---- */
  if (style.frontWing > 0) {
    const w = style.frontWing;
    const main = box(w, .034, .36, paint);
    main.position.set(0, .115, style.nose - .18);
    main.rotation.x = -.07;
    add(main);
    const flap = box(w * .93, .026, .22, carbon);
    flap.position.set(0, .175, style.nose - .30);
    flap.rotation.x = .28;
    add(flap);
    for (const s of [-1, 1]) {
      const ep = box(.024, .30, .44, paint);
      ep.position.set(s * w / 2, .19, style.nose - .27);
      add(ep);
    }
    strut(body, new THREE.Vector3(-.10, .22, style.nose - .42), new THREE.Vector3(-.10, .11, style.nose - .22), .02, carbon);
    strut(body, new THREE.Vector3(.10, .22, style.nose - .42), new THREE.Vector3(.10, .11, style.nose - .22), .02, carbon);
  }

  if (style.rearWing > .02) {
    const w = .62 + .48 * style.rearWing;
    const yTop = .96;
    const zR = -1.99;
    const main = box(w, .036, .34, carbon);
    main.position.set(0, yTop, zR);
    main.rotation.x = .12;
    add(main);
    const flap = box(w * .9, .028, .2, accentMat);
    flap.position.set(0, yTop + .115, zR - .13);
    flap.rotation.x = .36;
    add(flap);
    for (const s of [-1, 1]) {
      const ep = box(.024, .55, .46, paint);
      ep.position.set(s * w / 2, yTop - .14, zR - .02);
      add(ep);
    }
    const support = box(.045, .42, .1, carbon);
    support.position.set(0, yTop - .28, zR + .02);
    add(support);
    if (!low) {
      const drs = box(.16, .06, .1, dark);
      drs.position.set(0, yTop + .02, zR - .21);
      add(drs);
    }
  }

  /* ---- diffuser ---- */
  if (!low) {
    const diff = box(.92, .12, .5, carbon);
    diff.position.set(0, .17, -2.02);
    add(diff);
    for (let i = -2; i <= 2; i++) {
      const st = box(.018, .13, .46, dark);
      st.position.set(i * .17, .16, -2.03);
      add(st);
    }
  }

  /* ---- mirrors ---- */
  if (!low) {
    for (const s of [-1, 1]) {
      const stalk = strut(body, new THREE.Vector3(s * .26, .72, cockpitZ + .18), new THREE.Vector3(s * .42, .76, cockpitZ + .30), .014, carbon);
      const mir = box(.13, .06, .035, paint);
      mir.position.set(s * .45, .77, cockpitZ + .31);
      add(mir);
    }
  }

  /* ---- suspension ---- */
  const R = style.wheelR;
  const wt = style.trackW / 2;
  const fz = style.wheelbase / 2;
  const rz = -style.wheelbase / 2;
  if (!low) {
    for (const s of [-1, 1]) {
      strut(body, new THREE.Vector3(s * .29, .52, fz - .12), new THREE.Vector3(s * (wt - .05), R, fz), .021, dark);
      strut(body, new THREE.Vector3(s * .29, .30, fz - .34), new THREE.Vector3(s * (wt - .05), R, fz), .021, dark);
      strut(body, new THREE.Vector3(s * .27, .46, rz + .16), new THREE.Vector3(s * (wt - .05), R, rz), .021, dark);
      strut(body, new THREE.Vector3(s * .27, .30, rz - .08), new THREE.Vector3(s * (wt - .05), R, rz), .021, dark);
    }
  }

  /* ---- wheels ---- */
  const wheels = [];
  const wheelGeo = new THREE.CylinderGeometry(R, R, style.wheelW, low ? 16 : 26, 1, false);
  wheelGeo.rotateZ(Math.PI / 2);
  for (const front of [true, false]) {
    for (const s of [-1, 1]) {
      const pivot = new THREE.Group();
      pivot.position.set(s * wt, R, front ? fz : rz);
      root.add(pivot);
      const wheel = new THREE.Mesh(wheelGeo, [rubber, faceMat, faceMat]);
      wheel.castShadow = true;
      wheel.rotation.x = Math.PI / 2; // orient the texture upright on the caps
      pivot.add(wheel);
      wheels.push({ pivot, wheel, front, spin: 0 });
    }
  }

  /* ---- exhausts / rain light / decals ---- */
  if (!low) {
    if (style.vintage) {
      for (const s of [-1, 1]) {
        for (let i = 0; i < 3; i++) {
          strut(body, new THREE.Vector3(s * .30, .46 + i * .035, .55 + i * .22),
            new THREE.Vector3(s * .30, .47 + i * .035, 1.5 + i * .05), .028, chrome);
        }
      }
      const grille = new THREE.Mesh(new THREE.CircleGeometry(.135, 18), dark);
      grille.position.set(0, .49, style.nose + .005);
      add(grille);
    } else {
      const rainLight = box(.10, .07, .045, brake);
      rainLight.position.set(0, .38, -2.12);
      add(rainLight);
    }
    if (opts.number) {
      const decal = new THREE.Mesh(new THREE.PlaneGeometry(.44, .44), new THREE.MeshStandardMaterial({
        map: opts.number, transparent: true, roughness: .65, metalness: .05,
        depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2
      }));
      decal.rotation.x = -Math.PI / 2;
      decal.position.set(0, style.vintage ? .78 : .315, style.nose - .62);
      add(decal);
    }
    const stripe = box(.07, .012, 1.5, accentMat);
    stripe.position.set(0, style.vintage ? .79 : .785, style.vintage ? -.08 : -.75);
    add(stripe);
  }

  root.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });

  return {
    root, body, wheels, helmet, brakeLight: !style.vintage,
    materials: [paint, accentMat, carbon, dark, chrome, rubber, faceMat, glass, brake, headMat]
  };
}

export function orientCar(rig, layout, distance, lateral, dt, speed, steer, opts = {}) {
  const u = distance / layout.length;
  const s = layout.sample(u);
  const pos = s.pos.clone().addScaledVector(s.side, lateral);
  rig.root.position.set(pos.x, pos.y + .015, pos.z);
  const yaw = Math.atan2(s.tangent.x, s.tangent.z) + (opts.yawOffset || 0);
  rig.root.rotation.y = yaw;

  if (rig._yaw === undefined) rig._yaw = yaw;
  rig.root.rotation.y = yaw;

  const ratio = clamp(speed / 330, 0, 1);
  if (opts.player) {
    rig.body.rotation.z = -steer * ratio * .055;
    rig.body.rotation.x = clamp((opts.pitch || 0), -.03, .03);
    rig.body.position.y = Math.sin(performance.now() * .012) * .006 * ratio;
  } else {
    rig.body.rotation.z = Math.sin(performance.now() * .0015 + lateral) * .008;
    rig.body.rotation.x = 0;
  }

  const spin = speed / 3.6 / (opts.wheelR || .36) * dt;
  for (const w of rig.wheels) {
    w.spin -= spin;
    w.wheel.rotation.x = Math.PI / 2 + w.spin;
    if (w.front) w.pivot.rotation.y = steer * .45;
  }
  return { pos, yaw, tangent: s.tangent, side: s.side };
}

import * as THREE from '../vendor/three.module.js';
import { clamp, lerp, mulberry32, hashStr, smoothstep } from './util.js';

/* Builds a closed, arc-length-sampled circuit from a radial harmonic spline. */
export function buildLayout(track, eraIndex) {
  const rnd = mulberry32(hashStr(track.name) + 7);
  const lobes = clamp(Math.round(track.turns / 4), 3, 6);
  const ph = [rnd() * 6.283, rnd() * 6.283, rnd() * 6.283];
  const squash = .70 + rnd() * .34;
  const elevation = track.name === 'Spa-Francorchamps' ? 11
    : track.name === 'Nürburgring' ? 13
      : track.name === 'Monaco' ? 2.6
        : track.name === 'Circuit of the Americas' ? 8 : 5;

  const count = 18;
  const pts = [];
  for (let i = 0; i < count; i++) {
    const a = i / count * Math.PI * 2;
    const r = 1
      + .20 * Math.cos(lobes * a + ph[0])
      + .085 * Math.cos((lobes + 2) * a + ph[1])
      + .042 * Math.cos((lobes + 4) * a + ph[2]);
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r * squash;
    const y = elevation * (.5 * Math.sin(2 * a + ph[1]) + .3 * Math.sin(3 * a + ph[0]) + .2 * Math.sin(5 * a + ph[2]));
    pts.push(new THREE.Vector3(x, y, z));
  }

  let curve = new THREE.CatmullRomCurve3(pts, true, 'catmullrom', .5);
  const rawLen = curve.getLength();
  const scale = track.len / rawLen;
  pts.forEach(p => { p.x *= scale; p.z *= scale; });
  curve = new THREE.CatmullRomCurve3(pts, true, 'catmullrom', .5);

  const S = 1200;
  const sp = curve.getSpacedPoints(S);
  const samples = [];
  for (let i = 0; i < S; i++) {
    const p0 = sp[i], p1 = sp[(i + 1) % S];
    const tangent = p1.clone().sub(p0).normalize();
    const side = new THREE.Vector3(-tangent.z, 0, tangent.x).normalize();
    samples.push({ pos: p0.clone(), tangent, side });
  }
  const length = curve.getLength();
  const halfWidth = 5.35 + eraIndex * .2;

  const layout = {
    curve, samples, length, halfWidth, S,
    sample(u) {
      let f = u * S; f = ((f % S) + S) % S;
      const i = Math.floor(f), t = f - i;
      const a = samples[i], b = samples[(i + 1) % S];
      const pos = a.pos.clone().lerp(b.pos, t);
      const side = a.side.clone().lerp(b.side, t).normalize();
      const tangent = a.tangent.clone().lerp(b.tangent, t).normalize();
      return { pos, side, tangent };
    },
    nearest(x, z) {
      let best = 1e9, by = 0;
      for (let i = 0; i < S; i += 6) {
        const p = samples[i].pos;
        const dx = p.x - x, dz = p.z - z;
        const d = dx * dx + dz * dz;
        if (d < best) { best = d; by = p.y; }
      }
      return { dist: Math.sqrt(best), y: by };
    }
  };

  const hills = (x, z) =>
    6.5 * Math.sin(x * .0055 + 1.3) * Math.cos(z * .0047 - .8) +
    3.2 * Math.sin(x * .012 - .4) * Math.cos(z * .0105 + 2.1) +
    1.4 * Math.sin(x * .027 + 2.2) * Math.cos(z * .022);

  layout.heightAt = (x, z) => {
    const n = layout.nearest(x, z);
    const w = smoothstep(15, 100, n.dist);
    return lerp(n.y - .5, n.y + hills(x, z) * 1.15, w);
  };
  return layout;
}

export function makeRibbon(layout, cols, alongScale, material, renderOrder = 0) {
  const S = layout.samples.length;
  const pos = [], uv = [], idx = [];
  let dist = 0;
  for (let i = 0; i < S; i++) {
    const s = layout.samples[i];
    if (i > 0) dist += s.pos.distanceTo(layout.samples[i - 1].pos);
    for (const c of cols) {
      const p = s.pos.clone().addScaledVector(s.side, c.off);
      pos.push(p.x, p.y + c.y, p.z);
      uv.push(c.uv, dist / alongScale);
    }
  }
  const C = cols.length;
  for (let i = 0; i < S; i++) {
    const n = (i + 1) % S;
    for (let c = 0; c < C - 1; c++) {
      const a = i * C + c, b = a + 1, ci = n * C + c, d = ci + 1;
      idx.push(a, b, ci, b, d, ci);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  g.computeVertexNormals();
  const mesh = new THREE.Mesh(g, material);
  mesh.receiveShadow = true;
  mesh.renderOrder = renderOrder;
  return mesh;
}

export function buildRoad(layout, textures) {
  const group = new THREE.Group();
  const half = layout.halfWidth;

  const asphalt = new THREE.MeshStandardMaterial({
    map: textures.asphalt, bumpMap: textures.asphalt, bumpScale: .035,
    color: 0xf2f2f2, roughness: .84, metalness: .04, envMapIntensity: .55
  });
  const kerbMat = new THREE.MeshStandardMaterial({ map: textures.kerb, roughness: .62, metalness: .02 });
  const lineMat = new THREE.MeshStandardMaterial({ color: 0xe9e9e0, roughness: .7, metalness: .02 });
  const grassMat = new THREE.MeshStandardMaterial({ map: textures.grass, roughness: 1, metalness: 0, color: 0xe6e9df });

  const crown = [
    { off: -half, y: .005, uv: -half / 8 },
    { off: -half * .52, y: .025, uv: -half * .52 / 8 },
    { off: 0, y: .045, uv: 0 },
    { off: half * .52, y: .025, uv: half * .52 / 8 },
    { off: half, y: .005, uv: half / 8 }
  ];
  group.add(makeRibbon(layout, crown, 8, asphalt));

  for (const s of [-1, 1]) {
    const off = s * (half - .34);
    group.add(makeRibbon(layout, [
      { off: off - .07 * s, y: .055, uv: 0 },
      { off: off + .07 * s, y: .055, uv: 1 }
    ], 8, lineMat));
  }

  for (const s of [-1, 1]) {
    const a = s * (half - .02), b = s * (half + 1.45);
    group.add(makeRibbon(layout, [
      { off: Math.min(a, b), y: .06, uv: 0 },
      { off: Math.max(a, b), y: .06, uv: 1 }
    ], 4, kerbMat));
  }

  for (const s of [-1, 1]) {
    const a = s * (half + 1.45), b = s * (half + 13);
    group.add(makeRibbon(layout, [
      { off: Math.min(a, b), y: .015, uv: 0 },
      { off: Math.max(a, b), y: .015, uv: 2 }
    ], 10, grassMat));
  }

  // start / finish line
  const sample = layout.sample(0);
  const yaw = Math.atan2(sample.tangent.x, sample.tangent.z);
  const line = new THREE.Mesh(new THREE.PlaneGeometry(half * 2, 1.7), new THREE.MeshStandardMaterial({
    map: textures.checker, roughness: .7, metalness: .03,
    polygonOffset: true, polygonOffsetFactor: -2
  }));
  line.rotation.x = -Math.PI / 2;
  line.rotation.z = 0;
  line.rotation.y = yaw;
  line.position.copy(sample.pos);
  line.position.y += .12;
  line.receiveShadow = true;
  group.add(line);

  return { group, asphalt, kerbMat, grassMat };
}

export function buildTerrain(layout, textures) {
  let minX = 1e9, maxX = -1e9, minZ = 1e9, maxZ = -1e9;
  for (const s of layout.samples) {
    minX = Math.min(minX, s.pos.x); maxX = Math.max(maxX, s.pos.x);
    minZ = Math.min(minZ, s.pos.z); maxZ = Math.max(maxZ, s.pos.z);
  }
  const pad = 420;
  const span = Math.max(maxX - minX, maxZ - minZ) + pad * 2;
  const cx = (minX + maxX) / 2, cz = (minZ + maxZ) / 2;
  const N = 112;
  const geo = new THREE.PlaneGeometry(span, span, N, N);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const uv = geo.attributes.uv;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i) + cx;
    const z = pos.getZ(i) + cz;
    pos.setX(i, x); pos.setZ(i, z);
    pos.setY(i, layout.heightAt(x, z) - .06);
    uv.setXY(i, x / 17, z / 17);
  }
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ map: textures.grass, roughness: 1, metalness: 0, color: 0xdfe5d6 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  return { mesh, mat };
}

export function buildTrees(layout, count = 620) {
  const rnd = mulberry32(hashStr('trees' + layout.length));
  const trunks = [], foliage = [];
  let tries = 0;
  while (trunks.length < count && tries < count * 8) {
    tries++;
    const s = layout.samples[(rnd() * layout.S) | 0];
    const sideSign = rnd() > .5 ? 1 : -1;
    const off = sideSign * (16 + rnd() * 95);
    const p = s.pos.clone().addScaledVector(s.side, off).addScaledVector(s.tangent, (rnd() - .5) * 40);
    if (layout.nearest(p.x, p.z).dist < 14) continue;
    const y = layout.heightAt(p.x, p.z);
    const h = .8 + rnd() * 1.5;
    trunks.push({ x: p.x, y, z: p.z, s: h });
    foliage.push({ x: p.x, y: y + 2.4 * h + .6, z: p.z, s: h * (1.4 + rnd() * .8), hue: rnd() });
  }
  const trunkGeo = new THREE.CylinderGeometry(.16, .3, 3, 5, 1);
  trunkGeo.translate(0, 1.5, 0);
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3a2a, roughness: 1 });
  const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, trunks.length);
  const dummy = new THREE.Object3D();
  trunks.forEach((t, i) => {
    dummy.position.set(t.x, t.y, t.z);
    dummy.scale.set(t.s, t.s, t.s);
    dummy.rotation.y = t.s * 4.1;
    dummy.updateMatrix();
    trunkMesh.setMatrixAt(i, dummy.matrix);
  });
  trunkMesh.castShadow = true;

  const folGeo = new THREE.ConeGeometry(2.8, 7.4, 7, 1);
  const folMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: .95, flatShading: true });
  const folMesh = new THREE.InstancedMesh(folGeo, folMat, foliage.length);
  const col = new THREE.Color();
  foliage.forEach((t, i) => {
    dummy.position.set(t.x, t.y, t.z);
    dummy.scale.set(t.s, t.s * (1.1 + t.hue * .5), t.s);
    dummy.rotation.y = t.hue * 6.28;
    dummy.updateMatrix();
    folMesh.setMatrixAt(i, dummy.matrix);
    col.setHSL(.26 + t.hue * .06, .34 + t.hue * .18, .20 + t.hue * .09);
    folMesh.setColorAt(i, col);
  });
  folMesh.castShadow = true;
  folMesh.instanceMatrix.needsUpdate = true;
  trunkMesh.instanceMatrix.needsUpdate = true;
  if (folMesh.instanceColor) folMesh.instanceColor.needsUpdate = true;
  return { group: (() => { const g = new THREE.Group(); g.add(trunkMesh, folMesh); return g; })() };
}

