import * as THREE from '../vendor/three.module.js';
import { box, clamp, canvasTexture, mulberry32, hashStr } from './util.js';

export function buildScenery(layout, track, eraIndex, textures) {
  const group = new THREE.Group();
  const half = layout.halfWidth;
  const S = layout.S;
  const rnd = mulberry32(hashStr(track.name) + 99);

  /* ------------------------------ barriers ----------------------------- */
  const floaters = [];
  for (const s of [-1, 1]) {
    for (let i = 0; i < S; i += 2) {
      const sm = layout.samples[i];
      const pos = sm.pos.clone().addScaledVector(sm.side, s * (half + 7.2));
      let yaw = Math.atan2(sm.tangent.x, sm.tangent.z);
      if (s < 0) yaw += Math.PI;
      floaters.push({ pos, yaw, i, s });
    }
  }
  const modern = eraIndex >= 2;
  const barrierGeo = modern ? new THREE.BoxGeometry(5.2, .78, .22) : new THREE.BoxGeometry(2.5, .82, .82);
  const barrierMat = modern
    ? new THREE.MeshStandardMaterial({ map: textures.barrier, roughness: .55, metalness: .55 })
    : new THREE.MeshStandardMaterial({ color: 0xb79a5c, roughness: .95 });
  const barrierMesh = new THREE.InstancedMesh(barrierGeo, barrierMat, floaters.length);
  const dummy = new THREE.Object3D();
  const col = new THREE.Color();
  floaters.forEach((f, i) => {
    dummy.position.copy(f.pos);
    dummy.position.y += modern ? .39 : .41;
    dummy.rotation.set(0, f.yaw, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    barrierMesh.setMatrixAt(i, dummy.matrix);
    if (modern) {
      col.set(i % 9 === 0 ? 0xc23a2c : 0xffffff);
      barrierMesh.setColorAt(i, col);
    }
  });
  barrierMesh.castShadow = true;
  barrierMesh.receiveShadow = true;
  if (barrierMesh.instanceColor) barrierMesh.instanceColor.needsUpdate = true;
  group.add(barrierMesh);

  if (modern) {
    const postGeo = new THREE.CylinderGeometry(.06, .06, 1.1, 5);
    const postMat = new THREE.MeshStandardMaterial({ color: 0x8d9292, metalness: .8, roughness: .4 });
    const posts = new THREE.InstancedMesh(postGeo, postMat, floaters.length);
    floaters.forEach((f, i) => {
      dummy.position.copy(f.pos);
      dummy.position.y += .55;
      dummy.rotation.set(0, f.yaw, 0);
      dummy.scale.set(1, 1, 1);
      dummy.updateMatrix();
      posts.setMatrixAt(i, dummy.matrix);
    });
    posts.castShadow = true;
    group.add(posts);
  }

  /* ---------------------------- advertising ---------------------------- */
  const sponsorNames = [
    ['PIRELLI', '#1a1a1a', '#f2f2ec'], ['ROLEX', '#0f5132', '#e8d9a2'],
    ['DHL', '#f0c419', '#b3201a'], ['F1', '#c8102e', '#ffffff'],
    ['GENERATIONS', '#101510', '#d5f66a'], ['TURBO', '#1c3f6e', '#e9eef4']
  ];
  const sponsorTex = sponsorNames.map(([n, bg, fg]) => canvasTexture(512, 128, (ctx, w, h) => {
    ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = fg; ctx.font = '900 70px Arial, Helvetica, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(n, w / 2, h / 2 + 5);
  }));
  const boardGeo = new THREE.PlaneGeometry(11, 1.75);
  const boards = sponsorTex.map(() => []);
  for (const s of [-1, 1]) {
    const step = 46;
    for (let i = 0; i < S; i += step) {
      const sm = layout.samples[i];
      const pos = sm.pos.clone().addScaledVector(sm.side, s * (half + 6.25));
      pos.y += 1.55;
      const inward = sm.side.clone().multiplyScalar(-s);
      const yaw = Math.atan2(inward.x, inward.z);
      boards[(Math.random() * boards.length) | 0].push({ pos, yaw });
    }
  }
  boards.forEach((list, k) => {
    if (!list.length) return;
    const mat = new THREE.MeshStandardMaterial({
      map: sponsorTex[k], roughness: .62, metalness: .1, side: THREE.DoubleSide
    });
    mat.map.wrapS = mat.map.wrapT = THREE.RepeatWrapping;
    const mesh = new THREE.InstancedMesh(boardGeo, mat, list.length);
    list.forEach((b, i) => {
      dummy.position.copy(b.pos);
      dummy.rotation.set(0, b.yaw, 0);
      dummy.scale.set(1, 1, 1);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
    });
    mesh.castShadow = false;
    group.add(mesh);
  });

  /* ---------------------------- grandstands ---------------------------- */
  const concrete = new THREE.MeshStandardMaterial({ color: 0x9a9c96, roughness: .92 });
  const crowdMat = new THREE.MeshStandardMaterial({ map: textures.crowd, roughness: .95 });
  const roofMat = new THREE.MeshStandardMaterial({ color: 0x50565a, metalness: .55, roughness: .5 });
  const steel = new THREE.MeshStandardMaterial({ color: 0xb6bbba, metalness: .7, roughness: .35 });

  const makeStand = () => {
    const g = new THREE.Group();
    const base = box(27, 1.6, 14, concrete); base.position.set(0, .8, -6); g.add(base);
    for (let r = 0; r < 5; r++) {
      const row = box(26, .82, 2.2, crowdMat);
      row.position.set(0, 1.5 + r * .86, -1.2 - r * 2.15);
      g.add(row);
    }
    const back = box(26, 5.2, .5, concrete); back.position.set(0, 3.4, -11.4); g.add(back);
    const roof = box(27.5, .38, 14.4, roofMat); roof.position.set(0, 7.1, -6.1); g.add(roof);
    for (const x of [-12, 0, 12]) {
      const post = box(.35, 7, .35, steel); post.position.set(x, 3.5, -1.1); g.add(post);
    }
    return g;
  };
  const template = makeStand();
  const standUs = [.09, .24, .38, .52, .66, .8, .92];
  standUs.forEach((u, k) => {
    if (u < .035 || u > .965) return;
    const sm = layout.sample(u);
    const s = k % 2 ? 1 : -1;
    const pos = sm.pos.clone().addScaledVector(sm.side, s * (half + 24));
    const y = layout.heightAt(pos.x, pos.z);
    const st = template.clone();
    st.position.set(pos.x, y - .2, pos.z);
    st.lookAt(sm.pos.x, y + 2.4, sm.pos.z);
    group.add(st);
  });

  /* ---------------------------- pit building --------------------------- */
  const pit = new THREE.Group();
  const pitBody = box(118, 9, 19, new THREE.MeshStandardMaterial({ color: 0xb7b8b1, roughness: .8 }));
  pitBody.position.set(0, 4.5, -9.7);
  pit.add(pitBody);
  const pitRoof = box(124, .7, 23, new THREE.MeshStandardMaterial({ color: 0x3d4448, metalness: .45, roughness: .5 }));
  pitRoof.position.set(0, 9.2, -10);
  pit.add(pitRoof);
  const doorMat = new THREE.MeshStandardMaterial({ color: 0x14181b, roughness: .6, metalness: .3 });
  for (let i = -6; i <= 6; i++) {
    const door = box(6.6, 4.6, .3, doorMat);
    door.position.set(i * 8.6, 2.5, -.1);
    pit.add(door);
    const stripe = box(6.9, .28, .12, new THREE.MeshStandardMaterial({ color: 0xd5f66a, emissive: 0x8ea838, emissiveIntensity: .4 }));
    stripe.position.set(i * 8.6, 5.05, .05);
    pit.add(stripe);
  }
  const pitSign = new THREE.Mesh(new THREE.PlaneGeometry(34, 2.6), new THREE.MeshStandardMaterial({
    map: canvasTexture(512, 64, (ctx, w, h) => {
      ctx.fillStyle = '#101510'; ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = '#d5f66a'; ctx.font = '900 40px Arial, sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('PIT LANE  ·  F1', w / 2, h / 2 + 2);
    }), roughness: .6, side: THREE.DoubleSide
  }));
  pitSign.position.set(0, 7.1, .1);
  pit.add(pitSign);
  const pitSample = layout.sample(.012);
  const pitSide = 1;
  const pitPos = pitSample.pos.clone().addScaledVector(pitSample.side, pitSide * (half + 34));
  pit.position.set(pitPos.x, layout.heightAt(pitPos.x, pitPos.z), pitPos.z);
  pit.lookAt(pitSample.pos.x, pitPos.y + 3, pitSample.pos.z);
  group.add(pit);

  /* ------------------------------ gantry ------------------------------- */
  const gantry = new THREE.Group();
  const gMat = new THREE.MeshStandardMaterial({ color: 0x2c3236, metalness: .7, roughness: .4 });
  const lightHousing = new THREE.MeshStandardMaterial({ color: 0x121416, metalness: .4, roughness: .5 });
  const lightMat = new THREE.MeshStandardMaterial({ color: 0x2a0502, emissive: 0xff1c08, emissiveIntensity: 0, roughness: .35 });
  for (const s of [-1, 1]) {
    const tower = box(.9, 7.4, .9, gMat);
    tower.position.set(s * (half + 2.6), 3.7, 0);
    gantry.add(tower);
  }
  const beam = box(half * 2 + 6.2, 1.05, 1.5, gMat);
  beam.position.set(0, 7.2, 0);
  gantry.add(beam);
  for (let i = -2; i <= 2; i++) {
    const housing = box(.62, .82, .32, lightHousing);
    housing.position.set(i * 1.05, 6.35, -.55);
    gantry.add(housing);
    const lens = new THREE.Mesh(new THREE.CircleGeometry(.21, 16), lightMat);
    lens.position.set(i * 1.05, 6.35, -.73);
    lens.rotation.y = Math.PI;
    gantry.add(lens);
  }
  const banner = new THREE.Mesh(new THREE.PlaneGeometry(16, 1.15), new THREE.MeshStandardMaterial({
    map: canvasTexture(512, 64, (ctx, w, h) => {
      ctx.fillStyle = '#111510'; ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = '#f2f2e8'; ctx.font = '900 34px Arial, sans-serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('FORMULA ONE', w / 2, h / 2 + 2);
    }), roughness: .55, side: THREE.DoubleSide
  }));
  banner.position.set(0, 8.0, -.78);
  banner.rotation.y = Math.PI;
  gantry.add(banner);
  const gs = layout.sample(0);
  gantry.position.copy(gs.pos);
  gantry.rotation.y = Math.atan2(gs.tangent.x, gs.tangent.z);
  group.add(gantry);

  /* ------------------------- street buildings -------------------------- */
  if (track.mood === 'STREET CIRCUIT' || track.name === 'Albert Park') {
    const bGeo = new THREE.BoxGeometry(1, 1, 1);
    bGeo.translate(0, .5, 0);
    const bMat = new THREE.MeshStandardMaterial({ map: textures.windows, roughness: .85, metalness: .1 });
    const bMesh = new THREE.InstancedMesh(bGeo, bMat, 34);
    for (let i = 0; i < 34; i++) {
      const sm = layout.samples[(rnd() * S) | 0];
      const s = rnd() > .5 ? 1 : -1;
      const pos = sm.pos.clone().addScaledVector(sm.side, s * (half + 30 + rnd() * 26));
      dummy.position.set(pos.x, layout.heightAt(pos.x, pos.z) - 1, pos.z);
      dummy.rotation.set(0, Math.atan2(sm.tangent.x, sm.tangent.z) + (rnd() - .5) * .3, 0);
      dummy.scale.set(14 + rnd() * 26, 9 + rnd() * 26, 12 + rnd() * 22);
      dummy.updateMatrix();
      bMesh.setMatrixAt(i, dummy.matrix);
    }
    bMesh.castShadow = true;
    bMesh.receiveShadow = true;
    group.add(bMesh);
  }

  /* ------------------------------ hills -------------------------------- */
  const hillGeo = new THREE.ConeGeometry(1, 1, 7, 1);
  hillGeo.translate(0, .5, 0);
  const hillMat = new THREE.MeshStandardMaterial({ color: 0x53624b, roughness: 1, flatShading: true });
  const hills = new THREE.InstancedMesh(hillGeo, hillMat, 26);
  for (let i = 0; i < 26; i++) {
    const a = i / 26 * Math.PI * 2 + rnd() * .1;
    const dist = 700 + rnd() * 380;
    dummy.position.set(Math.cos(a) * dist, -18, Math.sin(a) * dist);
    dummy.rotation.set(0, rnd() * 6.28, 0);
    dummy.scale.set(160 + rnd() * 220, 70 + rnd() * 130, 160 + rnd() * 220);
    dummy.updateMatrix();
    hills.setMatrixAt(i, dummy.matrix);
  }
  group.add(hills);

  return { group, startLightMat: lightMat, standTemplate: template };
}

