import * as THREE from '../vendor/three.module.js';
import { canvasTexture } from './util.js';

const SKY_PRESETS = {
  DRY: {
    zenith: '#2e6db4', horizon: '#ccd7da', ground: '#59614f',
    sun: '#fff0cb', cloud: .52, sunInt: 1
  },
  WET: {
    zenith: '#5a6b73', horizon: '#9fabad', ground: '#474f49',
    sun: '#dde6e9', cloud: .95, sunInt: .18
  }
};

const VERT = `
varying vec3 vDir;
void main(){
  vDir = normalize(position);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const FRAG = `
uniform vec3 uZenith, uHorizon, uGround, uSunColor, uSunDir;
uniform float uCloud, uTime, uSunInt;
varying vec3 vDir;

float hash21(vec2 p){
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float noise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i), b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0)), d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p){
  float v = 0.0, a = 0.55;
  for(int i = 0; i < 5; i++){ v += a * noise(p); p = p * 2.03 + 17.0; a *= 0.5; }
  return v;
}
void main(){
  vec3 d = normalize(vDir);
  float h = max(d.y, 0.0);
  vec3 col = mix(uHorizon, uZenith, pow(h, 0.55));
  float sd = max(dot(d, normalize(uSunDir)), 0.0);
  col += uSunColor * (pow(sd, 1500.0) * 13.0 + pow(sd, 26.0) * 0.34 + pow(sd, 5.0) * 0.055) * uSunInt;
  if(d.y > 0.0){
    vec2 cp = d.xz / (d.y + 0.20) * 1.05 + vec2(uTime * 0.0035, uTime * 0.0012);
    float c = fbm(cp * 1.55);
    float c2 = fbm(cp * 4.1 + 7.0);
    float mask = smoothstep(0.015, 0.26, d.y);
    float clouds = smoothstep(0.47, 0.79, c * 0.66 + c2 * 0.34) * mask * uCloud;
    vec3 cloudCol = mix(vec3(0.60, 0.63, 0.66), uSunColor * 1.25, pow(sd, 3.0));
    col = mix(col, cloudCol, clouds * 0.88);
  }
  col = mix(col, uGround, smoothstep(0.0, -0.12, d.y));
  col = mix(col, uHorizon, smoothstep(0.10, -0.02, d.y));
  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}`;

export function createSkyDome(sunDir, weather = 'DRY') {
  const p = SKY_PRESETS[weather] || SKY_PRESETS.DRY;
  const uniforms = {
    uZenith: { value: new THREE.Color(p.zenith) },
    uHorizon: { value: new THREE.Color(p.horizon) },
    uGround: { value: new THREE.Color(p.ground) },
    uSunColor: { value: new THREE.Color(p.sun) },
    uSunDir: { value: sunDir.clone() },
    uCloud: { value: p.cloud },
    uSunInt: { value: p.sunInt },
    uTime: { value: 0 }
  };
  const material = new THREE.ShaderMaterial({
    uniforms, vertexShader: VERT, fragmentShader: FRAG,
    side: THREE.BackSide, depthWrite: false, fog: false
  });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(1200, 32, 20), material);
  mesh.frustumCulled = false;
  mesh.renderOrder = -10;
  return { mesh, material, uniforms };
}

export function setSkyWeather(sky, weather) {
  const p = SKY_PRESETS[weather] || SKY_PRESETS.DRY;
  sky.uniforms.uZenith.value.set(p.zenith);
  sky.uniforms.uHorizon.value.set(p.horizon);
  sky.uniforms.uGround.value.set(p.ground);
  sky.uniforms.uSunColor.value.set(p.sun);
  sky.uniforms.uCloud.value = p.cloud;
  sky.uniforms.uSunInt.value = p.sunInt;
}

export function makeEnvironment(renderer, sky) {
  const pmrem = new THREE.PMREMGenerator(renderer);
  const scene = new THREE.Scene();
  const sphere = new THREE.Mesh(new THREE.SphereGeometry(60, 32, 20), sky.material);
  scene.add(sphere);
  const target = pmrem.fromScene(scene, 0, .1, 200);
  pmrem.dispose();
  sphere.geometry.dispose();
  return target;
}

export function makeSunFlare() {
  const map = canvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(255,252,240,1)');
    g.addColorStop(.14, 'rgba(255,244,214,.9)');
    g.addColorStop(.4, 'rgba(255,224,170,.22)');
    g.addColorStop(1, 'rgba(255,210,150,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
  });
  const mat = new THREE.SpriteMaterial({
    map, transparent: true, blending: THREE.AdditiveBlending,
    depthTest: false, depthWrite: false, opacity: .55, toneMapped: false
  });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(300, 300, 1);
  sprite.renderOrder = 20;
  return sprite;
}

export function makeRain() {
  const map = canvasTexture(16, 128, (ctx, w, h) => {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, 'rgba(220,238,246,0)');
    g.addColorStop(.35, 'rgba(220,238,246,.55)');
    g.addColorStop(.85, 'rgba(232,246,252,.9)');
    g.addColorStop(1, 'rgba(232,246,252,0)');
    ctx.fillStyle = g;
    ctx.fillRect(w * .42, 0, w * .16, h);
  });
  const N = 2600;
  const pos = new Float32Array(N * 3);
  for (let i = 0; i < N; i++) {
    pos[i * 3] = (Math.random() - .5) * 130;
    pos[i * 3 + 1] = Math.random() * 55;
    pos[i * 3 + 2] = (Math.random() - .5) * 130;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const mat = new THREE.PointsMaterial({
    map, size: .55, transparent: true, opacity: 0, depthWrite: false,
    color: 0xd6e6ee, sizeAttenuation: true, blending: THREE.NormalBlending
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  points.visible = false;
  return points;
}

export { SKY_PRESETS };

